import sys
from sheet import evaluate, CycleError
print("recursionlimit:", sys.getrecursionlimit())

# deep reference chain: C0 -> C1 -> ... -> C4999
n = 5000
book = {"C%d" % i: "=C%d" % (i + 1) for i in range(n)}
book["C%d" % n] = "7"
try:
    print("PASS deep chain (%d cells) ->" % n, evaluate(book)["C0"])
except RecursionError as e:
    print("FAIL deep chain -> RecursionError")

# deep chain that ends in a cycle
book2 = {"C%d" % i: "=C%d" % (i + 1) for i in range(n)}
book2["C%d" % n] = "=C0"
try:
    evaluate(book2); print("FAIL deep cycle -> no raise")
except CycleError: print("PASS deep cycle -> CycleError")
except RecursionError: print("FAIL deep cycle -> RecursionError")

# very long left-assoc expression
expr = "=" + "+".join(["1"] * 5000)
try:
    print("PASS long sum ->", evaluate({"A": expr})["A"])
except RecursionError:
    print("FAIL long sum -> RecursionError")

# long chain of unary minus / parens (genuinely recursive; document the limit)
for depth in (100, 1000):
    try:
        v = evaluate({"A": "=" + "(" * depth + "1" + ")" * depth})["A"]
        print("PASS paren depth %d ->" % depth, v)
    except RecursionError:
        print("note: paren depth %d -> RecursionError" % depth)

# malformed formulas: should be a clear error, never a wrong number
for label, text in [
    ("trailing op", "=1+"), ("missing paren", "=(1+2"), ("stray paren", "=1+2)"),
    ("empty formula", "="), ("juxtaposed", "=1 2"), ("bad char", "=1%2"),
    ("non-numeric literal", "hello"), ("unknown ref", "=NOPE+1"),
]:
    try:
        print("     %-20s -> %r (no error)" % (label, evaluate({"A": text})["A"]))
    except (ValueError, KeyError) as e:
        print("PASS %-20s -> %s: %s" % (label, type(e).__name__, e))
    except Exception as e:
        print("FAIL %-20s -> %s: %s" % (label, type(e).__name__, e))
